# ---------------------------------------------------------------------------
# Parser
# ---------------------------------------------------------------------------

COLUMNS = [
    "rank", "name", "team",
    "adj_obpr", "adj_dbpr", "adj_bpr",
    "possessions",
    "raw_obpr", "raw_dbpr", "raw_bpr",
    "on_court_ortg", "on_court_drtg", "net_rtg",
    "value_extra",
]


def parse_em_text(raw_text: str) -> list[dict]:
    """Parse raw EM leaderboard text into a list of player dicts."""
    lines = [ln.strip() for ln in raw_text.splitlines() if ln.strip()]
    records = []
    i = 0
    while i < len(lines):
        try:
            rank = int(lines[i])
        except ValueError:
            i += 1
            continue

        if i + 13 >= len(lines):
            break

        name = lines[i + 1]
        team = lines[i + 2]
        nums_raw = lines[i + 3: i + 14]

        try:
            nums = [float(x) for x in nums_raw]
        except ValueError:
            i += 1
            continue

        records.append({
            "rank":          rank,
            "name":          name,
            "team":          team,
            "adj_obpr":      nums[0],
            "adj_dbpr":      nums[1],
            "adj_bpr":       nums[2],
            "possessions":   nums[3],
            "raw_obpr":      nums[4],
            "raw_dbpr":      nums[5],
            "raw_bpr":       nums[6],
            "on_court_ortg": nums[7],
            "on_court_drtg": nums[8],
            "net_rtg":       nums[9],
            "value_extra":   nums[10],
        })
        i += 14

    return records


def load_em_ratings(season_year: int) -> "list[dict]":
    """
    Return parsed Evan Miya BPR records for the given season ending year.
    E.g. season_year=2026 → 2025-26 season.
    Raises KeyError if that season has not been loaded yet.
    """
    if season_year not in RAW_DATA:
        available = sorted(RAW_DATA.keys())
        raise KeyError(
            f"No Evan Miya data for season_year={season_year}. "
            f"Available: {available}. Paste the leaderboard text into RAW_DATA[{season_year}]."
        )
    records = parse_em_text(RAW_DATA[season_year])
    # Deduplicate by (name, team) — handles double-paste (first N rows appearing twice).
    # Keep the entry with the lower rank (more reliable) when duplicates exist.
    seen: dict[tuple, dict] = {}
    for r in records:
        key = (r["name"], r["team"])
        if key not in seen or r["rank"] < seen[key]["rank"]:
            seen[key] = r
    return list(seen.values())


# ---------------------------------------------------------------------------
# Team name normalization helpers
# ---------------------------------------------------------------------------

# Common discrepancies between EM display names and our DB Team.name values.
# Keys = EM name, Values = our DB name (or a substring that uniquely matches).
_TEAM_NAME_MAP: dict[str, str] = {
    "Miami (Fla.)":    "Miami",
    "St. John's":      "St. John's",
    "NC State":        "NC State",
    "BYU":             "BYU",
    "USC":             "USC",
    "TCU":             "TCU",
    "VCU":             "VCU",
    "UCF":             "UCF",
    "SMU":             "SMU",
    "UAB":             "UAB",
    "LSU":             "LSU",
    "UCLA":            "UCLA",
    "UNC Wilmington":  "UNC Wilmington",
    "Sam Houston State": "Sam Houston",
    "McNeese State":   "McNeese",
    "George Washington": "George Washington",
}


def normalize_team_name(em_team: str) -> str:
    """Map EM display team name to a canonical string for fuzzy matching."""
    return _TEAM_NAME_MAP.get(em_team, em_team)
